import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.BZohXCq9.js";const m=JSON.parse('{"title":"Per-Instructor Commission (Instructor Share %) — How It Works","description":"","frontmatter":{},"headers":[],"relativePath":"PER_INSTRUCTOR_COMMISSION_GUIDE.md","filePath":"PER_INSTRUCTOR_COMMISSION_GUIDE.md"}'),s={name:"PER_INSTRUCTOR_COMMISSION_GUIDE.md"};function i(l,e,n,u,d,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="per-instructor-commission-instructor-share-—-how-it-works" tabindex="-1">Per-Instructor Commission (Instructor Share %) — How It Works <a class="header-anchor" href="#per-instructor-commission-instructor-share-—-how-it-works" aria-label="Permalink to &quot;Per-Instructor Commission (Instructor Share %) — How It Works&quot;">​</a></h1><p>This document explains the commission logic currently implemented in DSP: a <strong>platform default instructor share (%)</strong> plus an optional <strong>per-instructor override</strong>. It also explains where to configure it in the admin UI and how the split is applied across instant payments, deferred (T‑48) payments, and refunds.</p><hr><h2 id="_1-definitions-important" tabindex="-1">1) Definitions (important) <a class="header-anchor" href="#_1-definitions-important" aria-label="Permalink to &quot;1) Definitions (important)&quot;">​</a></h2><ul><li><strong>Instructor share (%)</strong>: the percentage of the lesson price that goes to the instructor.</li><li><strong>Admin / Platform share (%)</strong>: the remaining percentage kept by DSP (admin/platform commission).</li></ul><p>For percentage splits:</p><p>[ adminShare = 100 - instructorShare ]</p><hr><h2 id="_2-platform-default-applies-to-all-instructors-unless-overridden" tabindex="-1">2) Platform default (applies to all instructors unless overridden) <a class="header-anchor" href="#_2-platform-default-applies-to-all-instructors-unless-overridden" aria-label="Permalink to &quot;2) Platform default (applies to all instructors unless overridden)&quot;">​</a></h2><h3 id="where-to-set-it" tabindex="-1">Where to set it <a class="header-anchor" href="#where-to-set-it" aria-label="Permalink to &quot;Where to set it&quot;">​</a></h3><ul><li><strong>Admin Dashboard → Payment Management → Commission Management</strong></li></ul><h3 id="what-you-edit" tabindex="-1">What you edit <a class="header-anchor" href="#what-you-edit" aria-label="Permalink to &quot;What you edit&quot;">​</a></h3><ul><li><strong>Default instructor share (%)</strong> (editable) <ul><li>Example: set <strong>70</strong> → instructors get <strong>70%</strong>, admin gets <strong>30%</strong></li></ul></li></ul><h3 id="what-you-see-auto-calculated" tabindex="-1">What you see (auto-calculated) <a class="header-anchor" href="#what-you-see-auto-calculated" aria-label="Permalink to &quot;What you see (auto-calculated)&quot;">​</a></h3><ul><li><strong>Admin commission (%)</strong> (disabled, auto) <ul><li>Example: if Default instructor share is <strong>70</strong>, admin commission shows <strong>30</strong></li></ul></li></ul><h3 id="what-is-stored" tabindex="-1">What is stored <a class="header-anchor" href="#what-is-stored" aria-label="Permalink to &quot;What is stored&quot;">​</a></h3><ul><li><code>Admin.platformCommission.defaultInstructorRate</code> = instructor default share (%)</li><li><code>Admin.platformCommission.defaultRate</code> = admin share (%), stored to keep backward compatibility (it is set to (100 - defaultInstructorRate) when saving)</li></ul><hr><h2 id="_3-per-instructor-override-custom-for-one-instructor" tabindex="-1">3) Per-instructor override (custom for one instructor) <a class="header-anchor" href="#_3-per-instructor-override-custom-for-one-instructor" aria-label="Permalink to &quot;3) Per-instructor override (custom for one instructor)&quot;">​</a></h2><h3 id="where-to-set-it-1" tabindex="-1">Where to set it <a class="header-anchor" href="#where-to-set-it-1" aria-label="Permalink to &quot;Where to set it&quot;">​</a></h3><ul><li><strong>Admin Dashboard → Instructor Management</strong><ul><li>Open an instructor → <strong>Commission override</strong></li></ul></li></ul><h3 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h3><ul><li>Set <strong>% to instructor</strong> (0–100) <ul><li>Example: set <strong>60</strong> → this instructor gets <strong>60%</strong>, admin gets <strong>40%</strong></li></ul></li><li>Or click <strong>Use platform default</strong><ul><li>Clears the override so the platform default applies again</li></ul></li></ul><h3 id="what-is-stored-1" tabindex="-1">What is stored <a class="header-anchor" href="#what-is-stored-1" aria-label="Permalink to &quot;What is stored&quot;">​</a></h3><ul><li><code>Instructor.commission.instructorRate</code> = instructor override share (%) (nullable) <ul><li>If <code>null</code> → no override, platform default applies</li></ul></li></ul><hr><h2 id="_4-which-rule-is-used-priority-order" tabindex="-1">4) Which rule is used (priority order) <a class="header-anchor" href="#_4-which-rule-is-used-priority-order" aria-label="Permalink to &quot;4) Which rule is used (priority order)&quot;">​</a></h2><p>When calculating the split for a lesson amount, the system uses this order:</p><ol><li><strong>Per-instructor override</strong> (<code>Instructor.commission.instructorRate</code>) if set</li><li>Else <strong>platform default instructor share</strong> (<code>Admin.platformCommission.defaultInstructorRate</code>) if set</li><li>Else <strong>legacy platform default admin %</strong> (<code>Admin.platformCommission.defaultRate</code>) is used, and instructor gets the remainder</li></ol><p>This ensures:</p><ul><li>If you set a custom % for an instructor → it always wins for that instructor.</li><li>If you do not set a custom % → the platform default applies.</li></ul><hr><h2 id="_5-where-the-split-is-applied-all-payment-flows" tabindex="-1">5) Where the split is applied (all payment flows) <a class="header-anchor" href="#_5-where-the-split-is-applied-all-payment-flows" aria-label="Permalink to &quot;5) Where the split is applied (all payment flows)&quot;">​</a></h2><p>The split is applied in every payment path because the backend uses a single split function:</p><ul><li><code>server/src/services/stripeService.js</code> → <code>getCommissionSplit(...)</code></li></ul><p>This is used in:</p><ul><li><strong>Instant payment (pay now)</strong></li><li><strong>Deferred booking (save card)</strong></li><li><strong>T‑48 automatic charge job</strong></li><li><strong>T‑48 “requires action / 3DS” completion flow</strong></li><li><strong>Stripe webhook flows</strong></li></ul><p>So the per-instructor override affects both:</p><ul><li><strong>Instant bookings</strong></li><li><strong>Deferred / T‑48 bookings</strong></li></ul><hr><h2 id="_6-refund-behavior-same-split-reversed" tabindex="-1">6) Refund behavior (same split reversed) <a class="header-anchor" href="#_6-refund-behavior-same-split-reversed" aria-label="Permalink to &quot;6) Refund behavior (same split reversed)&quot;">​</a></h2><p>When a refund is approved:</p><ul><li>The <strong>student</strong> receives a refund for the <strong>full slot amount</strong> (one refund).</li><li>If the instructor share had already been transferred, the system creates a <strong>transfer reversal</strong> using: <ul><li><code>slot.instructorAmount</code> (the same instructor share that was applied at payment time)</li></ul></li><li>The platform commission is also reversed in the ledger using: <ul><li><code>slot.dspCommission</code> (the same commission applied at payment time)</li></ul></li></ul><p>This ensures the refund uses the <strong>same split amounts</strong> that were applied when the payment originally happened.</p><hr><h2 id="_7-quick-examples" tabindex="-1">7) Quick examples <a class="header-anchor" href="#_7-quick-examples" aria-label="Permalink to &quot;7) Quick examples&quot;">​</a></h2><h3 id="example-a-—-platform-default-only" tabindex="-1">Example A — platform default only <a class="header-anchor" href="#example-a-—-platform-default-only" aria-label="Permalink to &quot;Example A — platform default only&quot;">​</a></h3><ul><li>Default instructor share: <strong>70%</strong></li><li>No instructor override set</li><li>Lesson price: <strong>90 CHF</strong></li></ul><p>Result:</p><ul><li>Instructor: (90 × 0.70 = 63) CHF</li><li>Admin/platform: (90 × 0.30 = 27) CHF</li></ul><h3 id="example-b-—-per-instructor-override" tabindex="-1">Example B — per-instructor override <a class="header-anchor" href="#example-b-—-per-instructor-override" aria-label="Permalink to &quot;Example B — per-instructor override&quot;">​</a></h3><ul><li>Default instructor share: <strong>70%</strong></li><li>Instructor override: <strong>60%</strong></li><li>Lesson price: <strong>90 CHF</strong></li></ul><p>Result:</p><ul><li>Instructor: (90 × 0.60 = 54) CHF</li><li>Admin/platform: (90 × 0.40 = 36) CHF</li></ul><hr><h2 id="_8-how-to-test-quickly" tabindex="-1">8) How to test quickly <a class="header-anchor" href="#_8-how-to-test-quickly" aria-label="Permalink to &quot;8) How to test quickly&quot;">​</a></h2><ol><li>Set <strong>Default instructor share (%)</strong> in Commission Management (e.g. 70).</li><li>For Instructor A set override to 60; for Instructor B leave empty.</li><li>Make a new paid booking with each instructor (same amount).\\n4. Check Admin Transactions:\\n - Instructor A should reflect 60/40 split.\\n - Instructor B should reflect 70/30 split.\\n5. Approve a refund for one cancelled slot and verify the refund and reversal entries are created.</li></ol>',57)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
